func Test_WeeklyRecurrence_STATUS_WhenSerializedToJson_DeserializesAsEqual(t *testing.T) {
	t.Parallel()

	if testing.Short() {
		return
	}

	rapid.Check(t, RunJSONSerializationTestForWeeklyRecurrence_STATUS)
}

// RunJSONSerializationTestForWeeklyRecurrence_STATUS runs a test to see if a specific instance of WeeklyRecurrence_STATUS round trips to JSON and back losslessly
func RunJSONSerializationTestForWeeklyRecurrence_STATUS(t *rapid.T) {
	subject := WeeklyRecurrence_STATUSGenerator().Draw(t, "subject")
	// Serialize to JSON
	bin, err := json.Marshal(subject)
	if err != nil {
		t.Fatal(err)
	}

	// Deserialize back into memory
	var actual WeeklyRecurrence_STATUS
	err = json.Unmarshal(bin, &actual)
	if err != nil {
		t.Fatal(err)
	}

	// Check for outcome
	match := cmp.Equal(subject, actual, cmpopts.EquateEmpty())
	if !match {
		actualFmt := pretty.Sprint(actual)
		subjectFmt := pretty.Sprint(subject)
		result := diff.Diff(subjectFmt, actualFmt)
		t.Error(result)
	}
}

